/* asynchronous layer: one reactor thread */
for (;;) {
    int n = epoll_wait(ep, evs, MAX_EVENTS, -1);
    for (int i = 0; i < n; i++) queue_push(&q, evs[i].data.fd);
}
/* synchronous layer: N worker threads */
void *worker(void *arg) {
    for (;;) { int fd = queue_pop(&q); handle_request(fd); }
}
